function hookes(k, x){
  k=+k; x=+x; if(isNaN(k)||isNaN(x)) return {error:'请输入劲度系数 k 与形变量 x'};
  var F=k*x;
  var U=0.5*k*x*x;
  return {F:Math.round(F*1000)/1000, U:Math.round(U*1000)/1000, k:k, x:x,
    note:'F = k·x；弹性势能 U = ½k·x²'};
}
var EXPORTS={hookes:hookes};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HookesForgePure = EXPORTS; }
